class Solution {
    public long maximumAlternatingSubarraySum(int[] nums) {
        long NEG = Long.MIN_VALUE / 4;
        long plus = NEG, minus = NEG, ans = NEG;
        for (int x : nums) {
            long np = Math.max(x, minus + x);
            long nm = plus - x;
            plus = np;
            minus = nm;
            ans = Math.max(ans, Math.max(plus, minus));
        }
        return ans;
    }
}
